mapper.select:
select
delayData.delaynum as delaynum,
DATE_FORMAT(delayingData.mindate,'%Y-%m-%d') as mindate,
DATE_FORMAT(delayingData.maxdate,'%Y-%m-%d') as maxdate,
delayingData.delayingnum as delayingnum,
sendData.sendnum as sendnum,
manualData.manualnum as manualnum,
interfPass.interfPassnum as interfPassnum,
interfBack.interfBacknum as interfBacknum,
deleteTemp.deletenum as deletenum,
deleteTemp.countType as countType,
'14' as reporttype
FROM
(select count(ces1.SUBMIT_STATUS) as delaynum from CHB_EQU_SUB  ces1 WHERE DATE_FORMAT(ces1.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') < DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP},'%Y-%m-%d') and  ces1.SUBMIT_STATUS=#{NO_SUBMIT}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


) delayData ,
(select count(ces2.SUBMIT_STATUS) as delayingnum , min(ces2.SUBMIT_DEADLINE) as mindate, max(ces2.CHB_SUBMIT_DEADLINE) as maxdate from CHB_EQU_SUB  ces2 WHERE DATE_FORMAT(ces2.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') >= DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP},'%Y-%m-%d') and DATE_FORMAT(ces2.SUBMIT_DEADLINE,'%Y-%m-%d') <= DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP},'%Y-%m-%d') and ces2.SUBMIT_STATUS=#{NO_SUBMIT}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


) delayingData,
(select count(ces3.SUBMIT_STATUS) as sendnum from CHB_EQU_SUB  ces3 WHERE DATE_FORMAT(ces3.SUBMIT_DEADLINE,'%Y-%m-%d') > DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP},'%Y-%m-%d') and ces3.SUBMIT_STATUS=#{NO_SUBMIT}


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


) sendData,
(select count(ces3.SUBMIT_STATUS) as manualnum /*手工处理*/
from CHB_EQU_SUB  ces3
WHERE DATE_FORMAT(ces3.SUBMIT_TIME,'%Y-%m-%d') = DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP},'%Y-%m-%d')
and ces3.SUBMIT_STATUS='03' /*手工处理*/


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


) manualData,
(select count(ces3.SUBMIT_STATUS) as interfPassnum /*接口通过*/
from CHB_EQU_SUB  ces3
WHERE DATE_FORMAT(ces3.SUBMIT_TIME,'%Y-%m-%d') = DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP},'%Y-%m-%d')
and ces3.SUBMIT_STATUS='02' /*接口报送*/
and ces3.SUBMIT_FEEDBACK_STATUS in ('01','03') /*发送成功，中债通过*/


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


) interfPass,
(select count(ces3.SUBMIT_STATUS) as interfBacknum /*接口退回*/
from CHB_EQU_SUB  ces3
WHERE DATE_FORMAT(ces3.SUBMIT_TIME,'%Y-%m-%d') <= DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP},'%Y-%m-%d') 
and ces3.SUBMIT_STATUS='02' /*接口报送*/
and ces3.SUBMIT_FEEDBACK_STATUS in ('02','04','05') /*接口退回*/


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


) interfBack,
(SELECT
count(1) as deletenum,
'chbEquReg' as countType
FROM
CHB_EQU_SUB ces
WHERE ces.STATUS='03' and ces.SUBMIT_STATUS='01'
and DATE_FORMAT(ces.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') <= DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP},'%Y-%m-%d')


		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}




		#{item,jdbcType=VARCHAR}


)deleteTemp

