SELECT SUM(case when SEND_STATUS ='01' then 1 else 0 END ) as delaynum, /*已延期*/ min(case when SEND_STATUS ='02' then DATE_FORMAT(SUBMIT_DEADLINE, '%Y-%m-%d') else null END ) as mindate, max(case when SEND_STATUS ='02' then DATE_FORMAT(CHB_SUBMIT_DEADLINE, '%Y-%m-%d') else null END ) as maxdate, SUM(case when SEND_STATUS ='02' then 1 else 0 END ) as delayingnum, SUM(case when SEND_STATUS ='03' then 1 else 0 END ) as sendnum, SUM(case when SEND_STATUS ='04' then 1 else 0 END ) as manualnum, SUM(case when SEND_STATUS ='05' then 1 else 0 END ) as interfPassnum, SUM( case when SEND_STATUS ='06' then 1 else 0 END ) as interfBacknum, /*接口退回*/ null as deletenum, /*删除模版*/ null as countType, '01' as reporttype /*产品申报登记*/ FROM ( SELECT
SUBMIT_DEADLINE, CHB_SUBMIT_DEADLINE, PROD_ID FROM CHB_PRD_DECLARE_SUB WHERE 1=1
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
) P
