SELECT SUM(case when SEND_STATUS ='01' then 1 else 0 END ) as delaynum, min(case when SEND_STATUS ='02' then DATE_FORMAT(SUBMIT_DEADLINE, '%Y-%m-%d') else null END ) as mindate, max(case when SEND_STATUS ='02' then DATE_FORMAT(CHB_SUBMIT_DEADLINE, '%Y-%m-%d') else null END ) as maxdate, SUM(case when SEND_STATUS ='02' then 1 else 0 END ) as delayingnum, SUM(case when SEND_STATUS ='03' then 1 else 0 END ) as sendnum, SUM(case when SEND_STATUS ='04' then 1 else 0 END ) as manualnum, SUM(case when SEND_STATUS ='05' then 1 else 0 END ) as interfPassnum, SUM(case when SEND_STATUS ='06' then 1 else 0 END ) as interfBacknum, null as deletenum,/*删除模版*/ null as countType, '35' as reporttype /*销售结算资金交易登记*/ FROM ( SELECT
case when DATE_FORMAT(CHB_SUBMIT_DEADLINE, '%Y-%m-%d') < DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') and SEND_STATUS=#{NO_SUBMIT} then '01' when DATE_FORMAT(CHB_SUBMIT_DEADLINE, '%Y-%m-%d') >= DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') and DATE_FORMAT(SUBMIT_DEADLINE, '%Y-%m-%d') <= DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') and SEND_STATUS=#{NO_SUBMIT} then '02' when DATE_FORMAT(SUBMIT_DEADLINE, '%Y-%m-%d') > DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') and SEND_STATUS=#{NO_SUBMIT} then '03' when DATE_FORMAT(SUBMIT_TIME, '%Y-%m-%d') = DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') and SEND_STATUS = '03' then '04' when DATE_FORMAT(SUBMIT_TIME, '%Y-%m-%d') = DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') and SEND_STATUS = '02' /*接口报送*/ and SUBMIT_FEEDBACK_STATUS in ('01', '03') then '05' when DATE_FORMAT(SUBMIT_TIME, '%Y-%m-%d') <= DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') and SEND_STATUS = '02' /*接口报送*/ and SUBMIT_FEEDBACK_STATUS in ('02', '04', '05') then '06' when DATA_STATUS = '03'and SEND_STATUS = '01' and DATE_FORMAT(CHB_SUBMIT_DEADLINE, '%Y-%m-%d') <= DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') then '07' end SEND_STATUS, SUBMIT_DEADLINE, CHB_SUBMIT_DEADLINE FROM CHB_SALER_STL_DEAL_SUB WHERE 1=1
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
) P
