SELECT SUM(case when SEND_STATUS ='01' then 1 else 0 END ) as delaynum, min(case when SEND_STATUS ='02' then DATE_FORMAT(SUBMIT_DEADLINE, '%Y-%m-%d') else null END ) as mindate, max(case when SEND_STATUS ='02' then DATE_FORMAT(CHB_SUBMIT_DEADLINE, '%Y-%m-%d') else null END ) as maxdate, SUM(case when SEND_STATUS ='02' then 1 else 0 END ) as delayingnum, SUM(case when SEND_STATUS ='03' then 1 else 0 END ) as sendnum, SUM(case when SEND_STATUS ='04' then 1 else 0 END ) as manualnum, SUM(case when SEND_STATUS ='05' then 1 else 0 END ) as interfPassnum, SUM(case when SEND_STATUS ='06' then 1 else 0 END ) as interfBacknum, null as deletenum,/*删除模版*/ null as countType, '36' as reporttype /*理财业务销售数据月度统计表登记*/ FROM ( SELECT
case when DATE_FORMAT(PR.CHB_SUBMIT_DEADLINE, '%Y-%m-%d') < DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') and PR.SEND_STATUS=#{NO_SUBMIT} then '01' when DATE_FORMAT(PR.CHB_SUBMIT_DEADLINE, '%Y-%m-%d') >= DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') and DATE_FORMAT(PR.SUBMIT_DEADLINE, '%Y-%m-%d') <= DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') and PR.SEND_STATUS=#{NO_SUBMIT} then '02' when DATE_FORMAT(PR.SUBMIT_DEADLINE, '%Y-%m-%d') > DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') and PR.SEND_STATUS=#{NO_SUBMIT} then '03' when DATE_FORMAT(PR.SUBMIT_TIME, '%Y-%m-%d') = DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') and PR.SEND_STATUS = '03' then '04' when DATE_FORMAT(PR.SUBMIT_TIME, '%Y-%m-%d') = DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') and PR.SEND_STATUS = '02' /*接口报送*/ and PR.SUBMIT_FEEDBACK_STATUS in ('01', '03') then '05' when DATE_FORMAT(PR.SUBMIT_TIME, '%Y-%m-%d') <= DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') and PR.SEND_STATUS = '02' /*接口报送*/ and PR.SUBMIT_FEEDBACK_STATUS in ('02', '04', '05') then '06' when PR.DATA_STATUS = '03'and PR.SEND_STATUS = '01' and DATE_FORMAT(PR.CHB_SUBMIT_DEADLINE, '%Y-%m-%d') <= DATE_FORMAT(#{searchDate,jdbcType=TIMESTAMP}, '%Y-%m-%d') then '07' end SEND_STATUS, PR.SUBMIT_DEADLINE, PR.CHB_SUBMIT_DEADLINE FROM (SELECT DISTINCT termId,SEND_STATUS,CHB_SUBMIT_DEADLINE,SUBMIT_DEADLINE,ORG_CODE,SUBMIT_TIME,CREATE_DEPT,DATA_STATUS,DEPT_CODE,SUBMIT_FEEDBACK_STATUS FROM CHB_SALE_MONTH_REPORT) PR WHERE 1=1
